import type { UILocale } from '@molr/ui';
function waitDuration(seconds: number, locale: UILocale) {
  const hours = Math.floor(seconds / 3600), minutes = Math.floor(seconds % 3600 / 60), rest = seconds % 60;
  return locale === 'zh'
    ? `${hours ? `${hours}小时` : ''}${seconds >= 60 ? `${minutes}分钟` : ''}${rest}秒`
    : `${hours ? `${hours}h ` : ''}${seconds >= 60 ? `${minutes}m ` : ''}${rest}s`;
}
